   392→// ── Counter Animation ──────────────────────────────────────────────────────
   393→function animateCount(el) {
   394→    const target = parseInt(el.dataset.target) || 0;
   395→    if (target === 0) { el.textContent = '0'; return; }
   396→    const duration = 1200;
   397→    const start = performance.now();
   398→    const easeOut = t => 1 - Math.pow(1 - t, 3);
   399→    function step(now) {
   400→        const progress = Math.min((now - start) / duration, 1);
   401→        el.textContent = Math.round(easeOut(progress) * target).toLocaleString('id');
   402→        if (progress < 1) requestAnimationFrame(step);
   403→    }
   404→    requestAnimationFrame(step);
   405→}
