   411→        entries.forEach(entry => {
   412→            if (entry.isIntersecting) {
   413→                entry.target.querySelectorAll ? null : animateCount(entry.target);
   414→                animateCount(entry.target);
   415→                countIO.unobserve(entry.target);
   416→            }
   417→        });
   418→    }, { threshold: 0.3 });
